import{_ as o,o as t,c as d,a3 as c}from"./chunks/framework.cNy3aYYk.js";const k=JSON.parse('{"title":"Tenant API v1 — Short Links","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Short Links | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-short-links"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Short Links | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-short-links"}]]},"headers":[],"relativePath":"api/tenant-v1-short-links.md","filePath":"api/tenant-v1-short-links.md","lastUpdated":1794259478000}'),a={name:"api/tenant-v1-short-links.md"};function s(i,e,r,n,l,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="tenant-api-v1-—-short-links" tabindex="-1">Tenant API v1 — Short Links <a class="header-anchor" href="#tenant-api-v1-—-short-links" aria-label="Permalink to &quot;Tenant API v1 — Short Links&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:short-links</code>, plus permission middleware / policies.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-short-links-stats" tabindex="-1">GET <code>/short-links/stats</code> <a class="header-anchor" href="#get-short-links-stats" aria-label="Permalink to &quot;GET `/short-links/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload:</p><p><code>total_links</code>, <code>active_links</code>, <code>paused_links</code>, <code>total_clicks</code>, <code>clicks_last_7_days</code>, <code>top_links</code> (up to 5: <code>id</code>, <code>title</code>, <code>code</code>, <code>click_count</code>).</p><h2 id="short-links-crud" tabindex="-1">Short links CRUD <a class="header-anchor" href="#short-links-crud" aria-label="Permalink to &quot;Short links CRUD&quot;">​</a></h2><h3 id="get-short-links" tabindex="-1">GET <code>/short-links</code> <a class="header-anchor" href="#get-short-links" aria-label="Permalink to &quot;GET `/short-links`&quot;">​</a></h3><p>Query: <code>search</code> (title, destination_url), <code>status</code>, <code>type</code> (<code>redirect</code> | <code>splash</code> | <code>bio</code>), <code>campaign</code>, <code>tag</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>code</code>, <code>type</code>, <code>short_url</code>, <code>click_count</code>, <code>last_clicked_at</code>, and nested <code>creator</code>.</p><h3 id="post-short-links" tabindex="-1">POST <code>/short-links</code> <a class="header-anchor" href="#post-short-links" aria-label="Permalink to &quot;POST `/short-links`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>title</code></td><td>optional string</td></tr><tr><td><code>code</code></td><td>optional custom slug (3–64 chars, lowercase letters/numbers/hyphens, globally unique, not reserved); auto-generated when omitted</td></tr><tr><td><code>destination_url</code></td><td>required URL</td></tr><tr><td><code>status</code></td><td><code>active</code> | <code>paused</code> (default <code>active</code>)</td></tr><tr><td><code>type</code></td><td><code>redirect</code> | <code>splash</code> | <code>bio</code> (default <code>redirect</code>)</td></tr><tr><td><code>expires_at</code></td><td>optional datetime (workspace TZ in UI; stored UTC)</td></tr><tr><td><code>utm_source</code>, <code>utm_medium</code>, <code>utm_campaign</code>, <code>utm_term</code>, <code>utm_content</code></td><td>optional strings</td></tr><tr><td><code>splash_headline</code>, <code>splash_body</code>, <code>splash_cta_label</code>, <code>splash_logo_path</code>, <code>splash_delay_seconds</code>, <code>splash_theme</code></td><td>splash fields (<code>theme</code>: <code>light</code>|<code>dark</code>)</td></tr><tr><td><code>items</code></td><td>bio items array (<code>label</code>, <code>url</code>, optional <code>sort_order</code>, <code>icon</code>)</td></tr></tbody></table><p><code>uuid</code> and <code>short_url</code> are server-generated. <code>code</code> is set from the optional custom slug or auto-generated. <code>short_url</code> uses <code>SHORT_LINK_BASE_URL</code> (e.g. <code>https://go.elosync.com/r/launch-2026</code>). <code>code</code> cannot be changed after create.</p><h3 id="get-short-links-id" tabindex="-1">GET <code>/short-links/{id}</code> <a class="header-anchor" href="#get-short-links-id" aria-label="Permalink to &quot;GET `/short-links/{id}`&quot;">​</a></h3><p>Single short link resource.</p><h3 id="put-short-links-id" tabindex="-1">PUT <code>/short-links/{id}</code> <a class="header-anchor" href="#put-short-links-id" aria-label="Permalink to &quot;PUT `/short-links/{id}`&quot;">​</a></h3><p>Partial update of link fields.</p><h3 id="delete-short-links-id" tabindex="-1">DELETE <code>/short-links/{id}</code> <a class="header-anchor" href="#delete-short-links-id" aria-label="Permalink to &quot;DELETE `/short-links/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>short-links.delete</code>.</p><h3 id="post-short-links-id-restore" tabindex="-1">POST <code>/short-links/{id}/restore</code> <a class="header-anchor" href="#post-short-links-id-restore" aria-label="Permalink to &quot;POST `/short-links/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted link. Permission: <code>short-links.restore</code>.</p><h3 id="delete-short-links-id-force" tabindex="-1">DELETE <code>/short-links/{id}/force</code> <a class="header-anchor" href="#delete-short-links-id-force" aria-label="Permalink to &quot;DELETE `/short-links/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted link and its click rows. Permission: <code>short-links.force.delete</code>.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><h3 id="get-short-links-id-stats" tabindex="-1">GET <code>/short-links/{id}/stats</code> <a class="header-anchor" href="#get-short-links-id-stats" aria-label="Permalink to &quot;GET `/short-links/{id}/stats`&quot;">​</a></h3><p>Permission: <code>short-links.view_analytics</code>.</p><p>Query: optional <code>from</code>, <code>to</code> (workspace-local calendar dates <code>Y-m-d</code>).</p><p>Returns <code>click_count</code>, <code>range_click_count</code>, <code>unique_clicks</code> (distinct <code>ip_hash</code>), <code>last_clicked_at</code>, <code>clicks_by_day</code>, <code>clicks_by_hour</code>, <code>top_referrers</code>, <code>devices</code>, <code>browsers</code>, <code>os</code>.</p><h3 id="get-short-links-id-clicks" tabindex="-1">GET <code>/short-links/{id}/clicks</code> <a class="header-anchor" href="#get-short-links-id-clicks" aria-label="Permalink to &quot;GET `/short-links/{id}/clicks`&quot;">​</a></h3><p>Permission: <code>short-links.view_analytics</code>.</p><p>Paginated click log (<code>clicked_at</code>, <code>event</code>, <code>device_type</code>, <code>browser</code>, <code>os</code>, <code>referrer</code>, <code>user_agent</code>).</p><h3 id="get-short-links-id-export" tabindex="-1">GET <code>/short-links/{id}/export</code> <a class="header-anchor" href="#get-short-links-id-export" aria-label="Permalink to &quot;GET `/short-links/{id}/export`&quot;">​</a></h3><p>Permission: <code>short-links.view_analytics</code>.</p><p>CSV download of clicks (same optional <code>from</code> / <code>to</code> as stats). Columns: <code>clicked_at</code>, <code>event</code>, <code>device_type</code>, <code>browser</code>, <code>os</code>, <code>referrer</code>, <code>user_agent</code>.</p><h3 id="get-short-links-id-qr" tabindex="-1">GET <code>/short-links/{id}/qr</code> <a class="header-anchor" href="#get-short-links-id-qr" aria-label="Permalink to &quot;GET `/short-links/{id}/qr`&quot;">​</a></h3><p>Permission: <code>short-links.view</code>. Returns SVG QR for the public short URL.</p><h2 id="custom-short-domain" tabindex="-1">Custom short domain <a class="header-anchor" href="#custom-short-domain" aria-label="Permalink to &quot;Custom short domain&quot;">​</a></h2><h3 id="get-short-links-domain" tabindex="-1">GET <code>/short-links/domain</code> <a class="header-anchor" href="#get-short-links-domain" aria-label="Permalink to &quot;GET `/short-links/domain`&quot;">​</a></h3><p>Current proposed/verified hostname + TXT instruction.</p><h3 id="post-short-links-domain" tabindex="-1">POST <code>/short-links/domain</code> <a class="header-anchor" href="#post-short-links-domain" aria-label="Permalink to &quot;POST `/short-links/domain`&quot;">​</a></h3><p>Body: <code>{ &quot;hostname&quot;: &quot;links.example.com&quot; }</code>. Permission: <code>short-links.update</code>.</p><h3 id="post-short-links-domain-verify" tabindex="-1">POST <code>/short-links/domain/verify</code> <a class="header-anchor" href="#post-short-links-domain-verify" aria-label="Permalink to &quot;POST `/short-links/domain/verify`&quot;">​</a></h3><p>Verifies TXT <code>elosync-short-link-verify={token}</code>.</p><h3 id="delete-short-links-domain" tabindex="-1">DELETE <code>/short-links/domain</code> <a class="header-anchor" href="#delete-short-links-domain" aria-label="Permalink to &quot;DELETE `/short-links/domain`&quot;">​</a></h3><p>Removes the workspace custom short domain.</p><h2 id="public-redirect-central" tabindex="-1">Public redirect (central) <a class="header-anchor" href="#public-redirect-central" aria-label="Permalink to &quot;Public redirect (central)&quot;">​</a></h2><h3 id="get-r-code" tabindex="-1">GET <code>/r/{code}</code> <a class="header-anchor" href="#get-r-code" aria-label="Permalink to &quot;GET `/r/{code}`&quot;">​</a></h3><p>No authentication. Returns <code>302</code> to the destination URL with configured UTM query params appended.</p><ul><li><p>Primary lookup: <code>code</code> (auto-generated 7-char or custom vanity slug, e.g. <code>/r/launch-2026</code>)</p></li><li><p>Legacy: UUID still accepted (<code>/r/{uuid}</code>) for links created before 1.1.0 (UUID checked before slug format)</p></li><li><p>Active, non-expired, non-deleted link + entitled workspace → redirect + async click record</p></li><li><p>Paused, expired, missing, or soft-deleted → branded <code>404</code> HTML page (EloSync marketing CTAs)</p></li><li><p>Module not entitled → <code>403</code></p></li></ul><p>Rate limit: <code>short-link-redirects</code>.</p>',51)])])}const u=o(a,[["render",s]]);export{k as __pageData,u as default};
